-- Regional pack Kalimdor, Darnassus (content wave W01: the city in the crown of the world tree, its terraces and its temple). Written through the authoring archive
-- (tools/archive, CONTRIBUTING.md); the texts are in AzerothUnspoken_Kalimdor_enUS/Darnassus.lua and AzerothUnspoken_Kalimdor_itIT/Darnassus.lua. Built while
-- the character is in the area "teldrassil" and dropped when it leaves it (ADR 0048); the folder is loaded with the region
-- (ADR 0025). Races, classes, weather, the time of day and the moment are conditions inside the rules, never separate
-- packs. Subzone names are those of the English Classic client and are not yet confirmed in Forever (#36): a wrong
-- name only keeps a line silent.
